class FamilyTreeDeductionEnv:
    NAME_POOL = [
        "Ada", "Beno", "Cass", "Dov", "Ester", "Farin", "Gael", "Hira",
        "Iker", "Jora", "Kael", "Lira", "Moro", "Nils", "Orla", "Pell",
    ]
    ROLES = ["GF", "GM", "P1", "P2", "P3", "M1", "M3", "C1", "C2", "C3"]
    RELATION_WORDS = {
        "parent", "child", "grandparent", "grandchild",
        "sibling", "aunt_or_uncle", "niece_or_nephew", "cousin",
    }

    def __init__(self):
        self.max_steps = 10

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        names = self.rng.sample(self.NAME_POOL, 10)
        role = dict(zip(self.ROLES, names))
        self.all_people = list(names)

        self.parents = {}
        for child_role, par_roles in (
            ("P1", ("GF", "GM")), ("P2", ("GF", "GM")), ("P3", ("GF", "GM")),
            ("C1", ("P1", "M1")), ("C2", ("P3", "M3")), ("C3", ("P3", "M3")),
        ):
            self.parents[role[child_role]] = [role[par_roles[0]], role[par_roles[1]]]

        self.spouse = {}
        for x, y in (("GF", "GM"), ("P1", "M1"), ("P3", "M3")):
            self.spouse[role[x]] = role[y]
            self.spouse[role[y]] = role[x]

        self.children = {p: [] for p in self.all_people}
        for c, plist in self.parents.items():
            for p in plist:
                self.children[p].append(c)

        candidates = [
            (a, b) for a in self.all_people for b in self.all_people
            if a != b and self._relation(a, b) is not None
        ]
        self.query_a, self.query_b = self.rng.choice(candidates)
        self.correct_relation = self._relation(self.query_a, self.query_b)

        self.relevant = self._neighbors2(self.query_a) | self._neighbors2(self.query_b)
        self.reward_per = 0.4 / len(self.relevant)

        self.asked = set()
        self.steps = 0
        self.done = False

        obs = (
            f"A family has {len(self.all_people)} members: {', '.join(self.all_people)}.\n"
            f"Determine how {self.query_a} is related to {self.query_b} "
            f"(the answer must describe what {self.query_a} IS to {self.query_b}).\n"
            f"Valid relation words: {', '.join(sorted(self.RELATION_WORDS))}.\n"
            "Actions (exactly one per turn):\n"
            "  ASK <name>     - reveal that person's recorded parents, spouse, and children\n"
            "  ANSWER <word>  - submit your final relation guess (ends the episode)\n"
            f"You have {self.max_steps} total actions."
        )
        return obs, {"query_a": self.query_a, "query_b": self.query_b}

    def _ancestors_map(self, x):
        result = {}
        for p in self.parents.get(x, []):
            result.setdefault(p, 1)
            for gp in self.parents.get(p, []):
                result.setdefault(gp, 2)
        return result

    def _relation(self, a, b):
        if a == b:
            return None
        anc_a = self._ancestors_map(a)
        anc_b = self._ancestors_map(b)
        if b in anc_a:
            return "child" if anc_a[b] == 1 else "grandchild"
        if a in anc_b:
            return "parent" if anc_b[a] == 1 else "grandparent"
        common = set(anc_a) & set(anc_b)
        if not common:
            return None
        best = min(common, key=lambda c: anc_a[c] + anc_b[c])
        da, db = anc_a[best], anc_b[best]
        if da == 1 and db == 1:
            return "sibling"
        if da == 1 and db == 2:
            return "aunt_or_uncle"
        if da == 2 and db == 1:
            return "niece_or_nephew"
        if da == 2 and db == 2:
            return "cousin"
        return None

    def _neighbors2(self, x):
        s = {x}
        s |= set(self.parents.get(x, []))
        s |= set(self.children.get(x, []))
        for p in self.parents.get(x, []):
            s |= set(self.children.get(p, []))
            s |= set(self.parents.get(p, []))
        for c in self.children.get(x, []):
            s |= set(self.children.get(c, []))
        return s

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        remaining = self.max_steps - self.steps
        text = action.strip() if isinstance(action, str) else ""

        ask_match = re.match(r'^ASK\s+(.+)$', text, re.IGNORECASE)
        answer_match = re.match(r'^ANSWER\s+(.+)$', text, re.IGNORECASE)

        if ask_match:
            name_raw = ask_match.group(1).strip()
            match_name = next(
                (p for p in self.all_people if p.lower() == name_raw.lower()), None
            )
            if match_name is None:
                obs = (f"No family member named '{name_raw}'. "
                        f"Valid names: {', '.join(self.all_people)}. ({remaining} actions left)")
                return obs, 0.0, False, self.steps >= self.max_steps, {}

            plist = self.parents.get(match_name, [])
            sp = self.spouse.get(match_name)
            clist = self.children.get(match_name, [])
            obs = (
                f"Record for {match_name} — "
                f"parents: {', '.join(plist) if plist else 'none recorded'}; "
                f"spouse: {sp if sp else 'none recorded'}; "
                f"children: {', '.join(clist) if clist else 'none recorded'}. "
                f"({remaining} actions left)"
            )
            reward = 0.0
            if match_name not in self.asked and match_name in self.relevant:
                reward = self.reward_per
            self.asked.add(match_name)
            return obs, reward, False, self.steps >= self.max_steps, {}

        if answer_match:
            guess = answer_match.group(1).strip().lower()
            if guess not in self.RELATION_WORDS:
                obs = (f"'{guess}' is not a valid relation word. "
                        f"Valid words: {', '.join(sorted(self.RELATION_WORDS))}. ({remaining} actions left)")
                return obs, 0.0, False, self.steps >= self.max_steps, {}

            self.done = True
            if guess == self.correct_relation:
                obs = f"Correct! {self.query_a} is the {guess} of {self.query_b}."
                return obs, 0.6, True, False, {}
            obs = "Incorrect final answer. Episode over."
            return obs, 0.0, True, False, {}

        obs = (f"Malformed action. Use 'ASK <name>' or 'ANSWER <relation_word>'. "
                f"({remaining} actions left)")
        return obs, 0.0, False, self.steps >= self.max_steps, {}

import random


class FestivalCycleEnv:
    """Solver infers a hidden repeating festival cycle from probes and predicts future festival days."""

    MIN_PERIOD = 3
    MAX_PERIOD = 7
    MAX_DAY = 100
    STEP_LIMIT = 10

    def __init__(self):
        self.rng = None
        self.period = None
        self.phase = None
        self.reference_day = None
        self.known_day = None
        self.target_days = None
        self.steps = 0
        self.done = False
        self.known_festivals = set()
        self.milestone_awarded = False

    def _is_festival(self, day):
        return (day - 1) % self.period == self.phase

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.period = self.rng.randint(self.MIN_PERIOD, self.MAX_PERIOD)
        self.phase = self.rng.randint(0, self.period - 1)
        self.reference_day = self.rng.randint(20, 40)
        self.known_day = self.phase + 1
        self.known_festivals = {self.known_day}
        self.milestone_awarded = False
        self.steps = 0
        self.done = False

        targets = []
        d = self.reference_day + 1
        while len(targets) < 3:
            if self._is_festival(d):
                targets.append(d)
            d += 1
        self.target_days = targets

        obs = (
            "FESTIVAL CYCLE PUZZLE\n"
            "A festival recurs on a hidden fixed cycle: every P days starting from some\n"
            "offset, a festival is held (P is an unknown integer between 3 and 7).\n"
            f"Recorded fact: Day {self.known_day} is a confirmed festival day.\n"
            f"GOAL: determine the cycle and report the next THREE festival days that\n"
            f"occur strictly after day {self.reference_day}, in increasing order.\n"
            "ACTIONS:\n"
            "  CHECK <day>            -- ask whether <day> (integer 1-100) is a festival day\n"
            "  ANSWER <d1> <d2> <d3>  -- submit the next three festival days after day "
            f"{self.reference_day} (ends the episode)\n"
            f"You have {self.STEP_LIMIT} total actions (CHECK + ANSWER combined)."
        )
        return obs, {}

    def step(self, action):
        if self.done:
            return "Episode already finished.", 0.0, True, False, {}

        self.steps += 1
        action = (action or "").strip()
        parts = action.split()

        reward = 0.0
        terminated = False
        truncated = False

        if not parts:
            obs = "Empty action. Use 'CHECK <day>' or 'ANSWER <d1> <d2> <d3>'."
        elif parts[0].upper() == "CHECK":
            if len(parts) != 2 or not parts[1].lstrip("-").isdigit():
                obs = "Malformed CHECK. Format: CHECK <day> (integer 1-100)."
            else:
                day = int(parts[1])
                if day < 1 or day > self.MAX_DAY:
                    obs = f"Day out of range. Use a day between 1 and {self.MAX_DAY}."
                else:
                    is_fest = self._is_festival(day)
                    if is_fest:
                        if day not in self.known_festivals:
                            self.known_festivals.add(day)
                            if not self.milestone_awarded and len(self.known_festivals) >= 2:
                                reward += 0.25
                                self.milestone_awarded = True
                        obs = f"Day {day}: FESTIVAL."
                    else:
                        obs = f"Day {day}: not a festival."
        elif parts[0].upper() == "ANSWER":
            if len(parts) != 4 or not all(p.lstrip("-").isdigit() for p in parts[1:]):
                obs = "Malformed ANSWER. Format: ANSWER <d1> <d2> <d3> (three integers)."
            else:
                guesses = [int(p) for p in parts[1:4]]
                correct = sum(1 for g, t in zip(guesses, self.target_days) if g == t)
                reward += 0.25 * correct
                terminated = True
                obs = (
                    f"ANSWER submitted: {guesses}. Correct matches (in order): {correct}/3. "
                    f"True next festival days after day {self.reference_day}: {self.target_days}."
                )
        else:
            obs = "Unknown action. Use 'CHECK <day>' or 'ANSWER <d1> <d2> <d3>'."

        if not terminated and self.steps >= self.STEP_LIMIT:
            truncated = True
            obs += f" Step limit ({self.STEP_LIMIT}) reached without a submitted ANSWER."

        if terminated or truncated:
            self.done = True

        return obs, reward, terminated, truncated, {}

import random
import itertools


class FactoryChangeoverEnv:
    """Sequence factory jobs across three families to minimize hidden changeover cost."""

    FAMILIES = ('A', 'B', 'C')
    MAX_STEPS = 10

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        self.steps = 0
        self.done = False

        family_pool = list(self.FAMILIES) * 2
        self.rng.shuffle(family_pool)
        self.job_ids = [f"J{i+1}" for i in range(6)]
        self.job_family = dict(zip(self.job_ids, family_pool))
        self.proc_time = {jid: self.rng.randint(3, 9) for jid in self.job_ids}

        self.setup = {}
        for f1 in self.FAMILIES:
            for f2 in self.FAMILIES:
                if f1 != f2:
                    self.setup[(f1, f2)] = self.rng.randint(2, 9)

        self.known = {}
        self._max_setup = max(self.setup.values())
        self._optimal_cost = self._compute_optimal()
        self._worst_cost = max(1, (len(self.job_ids) - 1) * self._max_setup)

        lines = [
            "FACTORY LINE SEQUENCING - maximize throughput by minimizing changeover cost.",
            f"{len(self.job_ids)} jobs must run on one machine, each belongs to a family (A, B, or C).",
            "Same-family changeovers are free (cost 0). Cross-family changeover costs are HIDDEN and ASYMMETRIC",
            "(cost from A to B need not equal cost from B to A) - you must probe them.",
            "",
            "Jobs (id: family, processing_time):",
        ]
        for jid in self.job_ids:
            lines.append(f"  {jid}: family {self.job_family[jid]}, proc_time {self.proc_time[jid]}")
        lines += [
            "",
            "Actions (exactly one per turn):",
            "  PROBE <F1> <F2>   - reveal the changeover cost from family F1 to family F2 (F1,F2 in A,B,C, F1 != F2)",
            "  SEQUENCE <id,id,id,id,id,id> - commit a final visiting order of ALL job ids (comma-separated, each exactly once); ends the episode",
            f"You have {self.MAX_STEPS} steps total. Reward: 0.2 for a valid final sequence, plus up to 0.8 for how close its total changeover cost is to the true minimum.",
        ]
        obs = "\n".join(lines)
        return obs, {}

    def _compute_optimal(self):
        best = None
        for perm in itertools.permutations(self.FAMILIES):
            cost = sum(self.setup[(perm[i], perm[i + 1])] for i in range(len(perm) - 1))
            if best is None or cost < best:
                best = cost
        return best

    def _known_table(self):
        if not self.known:
            return "No changeover costs probed yet."
        rows = [f"  {f1}->{f2}: {c}" for (f1, f2), c in sorted(self.known.items())]
        return "Known changeover costs:\n" + "\n".join(rows)

    def step(self, action):
        if self.done:
            return "Episode already ended. Reset to play again.", 0.0, True, False, {}

        self.steps += 1
        text = (action or "").strip()
        parts = text.split()
        reward = 0.0
        terminated = False
        info = {}

        if not parts:
            obs = "Empty action. Use 'PROBE <F1> <F2>' or 'SEQUENCE <id,id,...>'.\n" + self._known_table()
        elif parts[0].upper() == "PROBE":
            if len(parts) != 3:
                obs = "Malformed PROBE. Use exactly: PROBE <F1> <F2>\n" + self._known_table()
            else:
                f1, f2 = parts[1].upper(), parts[2].upper()
                if f1 not in self.FAMILIES or f2 not in self.FAMILIES:
                    obs = f"Unknown family letter. Families are {self.FAMILIES}.\n" + self._known_table()
                elif f1 == f2:
                    obs = "Same-family changeover is always 0 - no need to probe that.\n" + self._known_table()
                else:
                    cost = self.setup[(f1, f2)]
                    self.known[(f1, f2)] = cost
                    obs = f"Changeover cost {f1}->{f2} = {cost}.\n" + self._known_table()
        elif parts[0].upper() == "SEQUENCE":
            if len(parts) < 2:
                obs = "Malformed SEQUENCE. Use: SEQUENCE <id,id,id,id,id,id>\n" + self._known_table()
            else:
                raw = " ".join(parts[1:])
                ids = [x.strip().upper() for x in raw.replace(",", " ").split() if x.strip()]
                if sorted(ids) != sorted(self.job_ids):
                    obs = (
                        f"Invalid sequence: must list all {len(self.job_ids)} job ids exactly once "
                        f"({', '.join(self.job_ids)}).\n" + self._known_table()
                    )
                else:
                    fams = [self.job_family[j] for j in ids]
                    achieved = sum(
                        self.setup.get((fams[i], fams[i + 1]), 0)
                        for i in range(len(fams) - 1)
                        if fams[i] != fams[i + 1]
                    )
                    performance = max(0.0, 1.0 - (achieved - self._optimal_cost) / self._worst_cost)
                    performance = min(1.0, performance)
                    reward = 0.2 + 0.8 * performance
                    terminated = True
                    self.done = True
                    info = {"achieved_cost": achieved, "optimal_cost": self._optimal_cost}
                    obs = (
                        f"Sequence accepted: {','.join(ids)}\n"
                        f"Total changeover cost = {achieved} (true minimum possible = {self._optimal_cost}).\n"
                        f"Episode complete. Reward this episode: {reward:.3f}"
                    )
        else:
            obs = "Unrecognized action. Use 'PROBE <F1> <F2>' or 'SEQUENCE <id,id,...>'.\n" + self._known_table()

        truncated = False
        if not terminated and self.steps >= self.MAX_STEPS:
            truncated = True
            self.done = True
            obs += f"\nStep limit ({self.MAX_STEPS}) reached without a committed sequence. Episode over."

        return obs, reward, terminated, truncated, info

import random
import re
import itertools
from collections import Counter


class LockNotesEnv:
    def __init__(self):
        self.max_steps = 10
        self.rng = None
        self.secret = None
        self.clue_texts = []
        self.clue_preds = []
        self.step_count = 0
        self.best_correct = 0
        self.finished = False
        self._action_re = re.compile(r'^\s*(TEST|SUBMIT)\s+(\d{4})\s*$', re.IGNORECASE)

    def _gen_sum(self, rng, secret):
        s = sum(secret)
        return (f"the four digits sum to {s}",
                lambda combo, s=s: sum(combo) == s)

    def _gen_even_count(self, rng, secret):
        k = sum(1 for d in secret if d % 2 == 0)
        return (f"exactly {k} of the four digits are even numbers",
                lambda combo, k=k: sum(1 for d in combo if d % 2 == 0) == k)

    def _gen_pos_parity(self, rng, secret):
        pos = rng.randrange(4)
        parity = "even" if secret[pos] % 2 == 0 else "odd"
        return (f"the digit in position {pos + 1} is {parity}",
                lambda combo, pos=pos, parity=parity: (combo[pos] % 2 == 0) == (parity == "even"))

    def _gen_compare(self, rng, secret):
        i, j = rng.sample(range(4), 2)
        if secret[i] > secret[j]:
            rel = "greater than"
        elif secret[i] < secret[j]:
            rel = "less than"
        else:
            rel = "equal to"
        def pred(combo, i=i, j=j, rel=rel):
            if rel == "greater than":
                return combo[i] > combo[j]
            if rel == "less than":
                return combo[i] < combo[j]
            return combo[i] == combo[j]
        return (f"the digit in position {i + 1} is {rel} the digit in position {j + 1}", pred)

    def _gen_max(self, rng, secret):
        m = max(secret)
        return (f"the largest digit in the combination is {m}",
                lambda combo, m=m: max(combo) == m)

    def _gen_min(self, rng, secret):
        m = min(secret)
        return (f"the smallest digit in the combination is {m}",
                lambda combo, m=m: min(combo) == m)

    def _gen_distinct(self, rng, secret):
        d = len(set(secret))
        return (f"the combination contains exactly {d} distinct digit value(s)",
                lambda combo, d=d: len(set(combo)) == d)

    def reset(self, seed=None):
        self.rng = random.Random(seed)
        rng = self.rng
        self.secret = [rng.randint(0, 9) for _ in range(4)]
        self.step_count = 0
        self.best_correct = 0
        self.finished = False

        kind_funcs = {
            'sum': self._gen_sum,
            'even_count': self._gen_even_count,
            'pos_parity': self._gen_pos_parity,
            'compare': self._gen_compare,
            'max': self._gen_max,
            'min': self._gen_min,
            'distinct': self._gen_distinct,
        }
        kinds = list(kind_funcs.keys())
        all_combos = list(itertools.product(range(10), repeat=4))

        best_attempt = None
        target_mid = 20
        for _ in range(40):
            chosen = rng.sample(kinds, 3)
            texts, preds = [], []
            for k in chosen:
                text, pred = kind_funcs[k](rng, self.secret)
                texts.append(text)
                preds.append(pred)
            count = sum(1 for c in all_combos if all(p(c) for p in preds))
            score = abs(count - target_mid)
            if best_attempt is None or score < best_attempt[3]:
                best_attempt = (texts, preds, count, score)
            if 4 <= count <= 60:
                break
        texts, preds, count, _ = best_attempt
        self.clue_texts = texts
        self.clue_preds = preds

        lines = [f"Clue note {i + 1}: {t}." for i, t in enumerate(self.clue_texts)]
        obs = (
            "You must reconstruct a 4-digit lock combination (each digit 0-9, "
            "digits may repeat) from torn clue notes.\n"
            + "\n".join(lines) + "\n\n"
            "Action format (send exactly one per turn):\n"
            "  TEST DDDD   - press a candidate combination against the lock's "
            "diagnostic pins. It reports how many digits are in the exactly "
            "correct position, and how many correct digits are present but in "
            "the wrong position. It does NOT end the episode.\n"
            "  SUBMIT DDDD - your real attempt to open the lock with this "
            "combination. This ENDS the episode whether or not it is correct.\n"
            f"You have {self.max_steps} actions total (TEST and SUBMIT both count "
            "against this limit). Example: TEST 4071"
        )
        return obs, {"max_steps": self.max_steps}

    def _score(self, guess):
        correct_pos = sum(g == s for g, s in zip(guess, self.secret))
        gc = Counter(guess)
        sc = Counter(self.secret)
        total_match = sum(min(gc[d], sc[d]) for d in gc)
        wrong_pos = total_match - correct_pos
        return correct_pos, wrong_pos

    def step(self, action):
        if self.finished:
            return ("Episode already ended.", 0.0, True, False, {})

        self.step_count += 1
        match = self._action_re.match(action or "")

        if not match:
            obs = (
                "Malformed action. Use exactly 'TEST DDDD' or 'SUBMIT DDDD' "
                "where DDDD is four digits, e.g. TEST 4071."
            )
            truncated = self.step_count >= self.max_steps
            if truncated:
                self.finished = True
            return (obs, 0.0, False, truncated, {"step": self.step_count})

        verb = match.group(1).upper()
        guess = [int(ch) for ch in match.group(2)]
        correct_pos, wrong_pos = self._score(guess)

        increase = max(0, correct_pos - self.best_correct)
        reward = (increase / 4.0) * 0.6
        self.best_correct = max(self.best_correct, correct_pos)

        if verb == "TEST":
            obs = (
                f"Diagnostic result for {''.join(map(str, guess))}: "
                f"{correct_pos} digit(s) in the exactly correct position; "
                f"{wrong_pos} more correct digit(s) present but in the wrong position."
            )
            truncated = self.step_count >= self.max_steps
            if truncated:
                self.finished = True
            info = {"step": self.step_count, "correct_positions": correct_pos,
                     "wrong_position_matches": wrong_pos}
            return (obs, reward, False, truncated, info)

        # SUBMIT
        self.finished = True
        if correct_pos == 4:
            reward += 0.4
            obs = f"The lock opens with {''.join(map(str, guess))}. Success."
        else:
            obs = (
                f"The lock does not open. {''.join(map(str, guess))} had "
                f"{correct_pos} digit(s) in the correct position and "
                f"{wrong_pos} correct digit(s) in the wrong position. "
                "That was your real attempt; the episode has ended."
            )
        info = {"step": self.step_count, "correct_positions": correct_pos,
                "wrong_position_matches": wrong_pos, "secret": self.secret}
        return (obs, reward, True, False, info)
